// Teaching snapshots derived from model frames, not a second protocol simulator.
export const apiGuides={
 basics:{goal:'อ่านคำขอและแยก 200 สำเร็จ / 404 ไม่พบ / 400 ข้อมูลไม่ถูกต้อง',input:'ข้อความ',sent:'คำขอ HTTP ที่ส่ง',received:'คำตอบ HTTP ของคำขอนี้',contract:'GET /products/{id}\nid ต้องเป็นตัวเลข · ID 1 มีสินค้า · ID 99 ไม่มีสินค้า'},
 rest:{goal:'เลือก method ให้ตรงงาน และอ่าน status, headers, body แยกกัน',input:'ชื่อสินค้าใหม่',sent:'คำขอ HTTP ที่ส่ง',received:'Status / Headers / Body ที่ได้รับ',contract:'GET /products/{id}: อ่าน\nPOST /products: สร้างเมื่อ name ไม่ว่าง\nPATCH /products/{id}: ตัวอย่างนี้ไม่รองรับ'},
 graphql:{goal:'เลือก fields ตาม schema และเห็นว่าคำขอผิดถูกหยุดก่อน resolver',input:'ข้อความ',sent:'Query ที่ส่ง',received:'GraphQL response',contract:'type Query { product(id: Int!): Product }\ntype Product { name: String, price: Int }\nproduct อาจเป็น null · password ไม่มีใน schema'},
 grpc:{goal:'นับ messages ใน RPC เดิม และแยกข้อความจาก status ปิด RPC',input:'ข้อความ',sent:'Method และ typed request',received:'Messages ที่ได้รับ / RPC status',contract:'ProductRequest { id: integer }\nGetProduct(ProductRequest) → Product (หนึ่ง message)\nWatchProducts(ProductRequest) → stream Product\ncontract ย่อเพื่ออ่าน ไม่ใช่ไฟล์ .proto ที่ compile ได้'},
 soap:{goal:'หา Envelope, Body และชื่อ Fault โดยไม่สับสนเวอร์ชัน',input:'ข้อความ',sent:'SOAP XML ที่ส่ง',received:'SOAP XML ที่ได้รับ',contract:'SOAP 1.2 Envelope → Body → GetProduct(id)\nOperation ผิด → Sender Fault\nSOAP 1.1 เข้า service นี้ → SOAP 1.1 VersionMismatch'},
 websocket:{goal:'เห็นช่วง handshake ก่อนเปิดช่อง messages สองทิศทาง',input:'ข้อความสนทนาที่ Client ส่ง',sent:'Handshake / ข้อความ Client',received:'Handshake / ข้อความ Server',contract:'classic HTTP/1.1 Upgrade → 101 → WebSocket messages\nไม่ใช้ HTTP request ใหม่สำหรับทุก message'},
 sse:{goal:'นับ events ใน response เดียว และอ่าน last event ID เมื่อเชื่อมใหม่',input:'ข้อความใน Event จาก Server',sent:'คำขอเปิด Event stream',received:'Headers / Events ใน stream เดียว',contract:'GET /events → text/event-stream\nServer → Client เท่านั้นใน stream นี้\nreplay หลัง Last-Event-ID เป็น policy ที่ Lab รองรับ'},
 'long-polling':{goal:'แยกแต่ละรอบ: ส่งคำขอ → รอ → ตอบจบ → ขอใหม่',input:'ข้อความของ Event ที่รอรับ',sent:'คำขอ HTTP รอบปัจจุบัน',received:'คำตอบของรอบปัจจุบัน',contract:'GET /events?after=cursor\nรอ Event → 200 · ครบเวลารอ → 204 (policy ของ Lab)\nทุก response จบแล้วจึงเริ่ม request ใหม่'},
 webhooks:{goal:'เห็น callback, ACK ที่หาย และ ID เดิมที่ไม่เพิ่มงานซ้ำ',input:'รายละเอียด Event ที่ต้นทางส่ง',sent:'HTTP delivery จากต้นทาง',received:'คำตอบที่ต้นทางได้รับ',contract:'POST /hooks/orders { id: "evt-1", type: "order.created" }\nบันทึก ID + รับงานแบบ atomic ในตัวอย่าง\nACK ยืนยันรับงาน ไม่ยืนยันงานปลายทางเสร็จ'}
};
export function apiVisual(model,index){
 const frames=model.steps.slice(0,index+1),f=frames.at(-1),fields=Object.fromEntries(frames.flatMap(s=>s.fields)),responses=frames.filter(s=>s.response!==undefined),kind=model.kind;
 const cell=(label,value,state='pending')=>({label,value:String(value),state});
 if(kind==='graphql'){const selected=String(fields.Selected).split(' '),validated=fields.Validation==='PASS';return ['name','price','password'].map(k=>cell(k,k==='password'?'ไม่มีใน schema':selected.includes(k)?(validated?'เลือกและผ่าน':'ขอตรวจ'):'ไม่ขอ',k==='password'&&selected.includes(k)?'blocked':selected.includes(k)&&validated?'ok':'pending'));}
 if(kind==='grpc')return [cell('RPC หนึ่งครั้ง',fields.Method),cell('Messages รับแล้ว',responses.length,responses.length?'ok':'pending'),cell('Deadline / Status',fields['gRPC status']||'ยังรอ · เวลาเชิงแนวคิด',f.status==='blocked'?'blocked':fields['gRPC status']?'ok':'pending')];
 if(kind==='webhooks'){const count=Number(fields.Processed||0);return [cell('Event ID','evt-1'),cell('งานรับใหม่',count,count?'ok':'pending'),cell('ตรวจ ID เดิม',fields.Duplicate?'ซ้ำ → ไม่เพิ่มงาน':fields.Signature||'รอตรวจ',fields.Duplicate?'ok':model.scenario===2&&index>0?'blocked':'pending')];}
 if(kind==='long-polling'){const round=frames.filter(s=>s.request!==undefined).length,pending=f.nodeUpdates.server?.includes('PENDING');return [cell('รอบคำขอ',round),cell('สถานะรอบนี้',pending?'PENDING · ยังไม่ตอบ':f.status==='blocked'?'ขาดการเชื่อมต่อ':responses.length?'ตอบจบแล้ว':'กำลังส่ง',pending?'pending':f.status==='blocked'?'blocked':'ok'),cell('Cursor ล่าสุด',f.nodeUpdates.client?.includes('cursor')?f.nodeUpdates.client:'cursor = 0')];}
 if(kind==='sse')return [cell('HTTP response',frames.some(s=>s.responseHead)?'หนึ่ง stream เปิดอยู่':'ยังไม่เปิด'),cell('Events รับแล้ว',responses.length,responses.length?'ok':'pending'),cell('Event ID ล่าสุด',responses.length?fields['Event ID']:'ยังไม่มี',f.status==='blocked'?'blocked':'pending')];
 if(kind==='websocket')return [cell('ช่วงการสื่อสาร',frames.some(s=>s.responseHead)?'WebSocket':'HTTP handshake'),cell('ช่องที่เปิด',f.nodeUpdates.client||'ยังไม่เปิด',f.status==='blocked'?'blocked':'pending'),cell('App messages รับ',responses.filter(s=>!s.title.includes('WebSocket')).length)];
 if(kind==='soap')return [cell('Envelope ที่ส่ง',model.scenario===2?'SOAP 1.1':'SOAP 1.2'),cell('Body operation',model.scenario===1?'RemoveEverything':'GetProduct'),cell('ผลตรวจ / Fault',fields.Fault||fields.Result||'รอตรวจ',f.status==='blocked'?'blocked':responses.length?'ok':'pending')];
 return [cell('Method',fields.Method),cell('Path',fields.Path),cell('HTTP status',fields.HTTP||'ยังรอ',f.status==='blocked'?'blocked':responses.length?'ok':'pending')];
}
